    testcases: [{"input":[[2,4,3],[5,6,4]],"output":[7,0,8]},{"input":[[0],[0]],"output":[0]},{"input":[[9,9,9,9,9,9,9],[9,9,9,9]],"output":[8,9,9,9,0,0,0,1]}],
    descriptionHtml: "<p>给你两个&nbsp;<strong>非空</strong> 的链表，表示两个非负的整数。它们每位数字都是按照&nbsp;<strong>逆序</strong>&nbsp;的方式存储的，并且每个节点只能存储&nbsp;<strong>一位</strong>&nbsp;数字。</p>\r\n\r\n<p>请你将两个数相加，并以相同形式返回一个表示和的链表。</p>\r\n\r\n<p>你可以假设除了数字 0 之外，这两个数都不会以 0&nbsp;开头。</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong class=\"example\">示例 1：</strong></p>\r\n<img src=\"https://blog-1304855543.cos.ap-guangzhou.myqcloud.com/blog/image-20240823101925768.png\" alt=\"image-20240823101925768\"  />\r\n\r\n<pre>\r\n<strong>输入：</strong>l1 = [2,4,3], l2 = [5,6,4]\r\n<strong>输出：</strong>[7,0,8]\r\n<strong>解释：</strong>342 + 465 = 807.\r\n</pre>\r\n\r\n<p><strong class=\"example\">示例 2：</strong></p>\r\n\r\n<pre>\r\n<strong>输入：</strong>l1 = [0], l2 = [0]\r\n<strong>输出：</strong>[0]\r\n</pre>\r\n\r\n<p><strong class=\"example\">示例 3：</strong></p>\r\n\r\n<pre>\r\n<strong>输入：</strong>l1 = [9,9,9,9,9,9,9], l2 = [9,9,9,9]\r\n<strong>输出：</strong>[8,9,9,9,0,0,0,1]\r\n</pre>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>提示：</strong></p>\r\n\r\n<ul>\r\n\t<li>每个链表中的节点数在范围 <code>[1, 100]</code> 内</li>\r\n\t<li><code>0 &lt;= Node.val &lt;= 9</code></li>\r\n\t<li>题目数据保证列表表示的数字不含前导零</li>\r\n</ul>",
    python: "class Solution:\r\n    def addTwoNumbers(\r\n        self, l1: Optional[ListNode], l2: Optional[ListNode]\r\n    ) -> Optional[ListNode]:\r\n        dummy = ListNode()\r\n        carry, curr = 0, dummy\r\n        while l1 or l2 or carry:\r\n            s = (l1.val if l1 else 0) + (l2.val if l2 else 0) + carry\r\n            carry, val = divmod(s, 10)\r\n            curr.next = ListNode(val)\r\n            curr = curr.next\r\n            l1 = l1.next if l1 else None\r\n            l2 = l2.next if l2 else None\r\n        return dummy.next",
    java: "class Solution {\r\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\r\n        ListNode dummy = new ListNode(0);\r\n        int carry = 0;\r\n        ListNode cur = dummy;\r\n        while (l1 != null || l2 != null || carry != 0) {\r\n            int s = (l1 == null ? 0 : l1.val) + (l2 == null ? 0 : l2.val) + carry;\r\n            carry = s / 10;\r\n            cur.next = new ListNode(s % 10);\r\n            cur = cur.next;\r\n            l1 = l1 == null ? null : l1.next;\r\n            l2 = l2 == null ? null : l2.next;\r\n        }\r\n        return dummy.next;\r\n    }\r\n}",
