    testcases: [{"input":[[3,9,20,null,null,15,7]],"output":true},{"input":[[1,2,2,3,3,null,null,4,4]],"output":false},{"input":[[]],"output":true}],
    descriptionHtml: "<p>给定一个二叉树，判断它是否是 <span data-keyword=\"height-balanced\">平衡二叉树</span> &nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>示例 1：</strong></p>\r\n<img src=\"https://blog-1304855543.cos.ap-guangzhou.myqcloud.com/blog/image-20240823110443846.png\" alt=\"image-20240823110443846\"  />\r\n\r\n<pre>\r\n<strong>输入：</strong>root = [3,9,20,null,null,15,7]\r\n<strong>输出：</strong>true\r\n</pre>\r\n\r\n<p><strong>示例 2：</strong></p>\r\n<img src=\"https://blog-1304855543.cos.ap-guangzhou.myqcloud.com/blog/image-20240823110500151.png\" alt=\"image-20240823110500151\"  />\r\n\r\n<pre>\r\n<strong>输入：</strong>root = [1,2,2,3,3,null,null,4,4]\r\n<strong>输出：</strong>false\r\n</pre>\r\n\r\n<p><strong>示例 3：</strong></p>\r\n\r\n<pre>\r\n<strong>输入：</strong>root = []\r\n<strong>输出：</strong>true\r\n</pre>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>提示：</strong></p>\r\n\r\n<ul>\r\n\t<li>树中的节点数在范围 <code>[0, 5000]</code> 内</li>\r\n\t<li><code>-10<sup>4</sup> &lt;= Node.val &lt;= 10<sup>4</sup></code></li>\r\n</ul>",
    python: "class Solution:\r\n    def isBalanced(self, root: Optional[TreeNode]) -> bool:\r\n        def height(root):\r\n            if root is None:\r\n                return 0\r\n            l, r = height(root.left), height(root.right)\r\n            if l == -1 or r == -1 or abs(l - r) > 1:\r\n                return -1\r\n            return 1 + max(l, r)\r\n\r\n        return height(root) >= 0",
    java: "class Solution {\r\n    public boolean isBalanced(TreeNode root) {\r\n        return height(root) >= 0;\r\n    }\r\n\r\n    private int height(TreeNode root) {\r\n        if (root == null) {\r\n            return 0;\r\n        }\r\n        int l = height(root.left);\r\n        int r = height(root.right);\r\n        if (l == -1 || r == -1 || Math.abs(l - r) > 1) {\r\n            return -1;\r\n        }\r\n        return 1 + Math.max(l, r);\r\n    }\r\n}",
